//
// Origin: written for this core by hand (not generated by the Quartus IP
//         tools): one altera_pll instance in the form of PSX_MiSTer's
//         Quartus-generated rtl/pll/pll_0002.v, with the output of
//         rtl/pll2/pll2_0002.v.
// Evidence: MAME 0.288 zn.cpp:94 (CXD8654Q at 53.693175 MHz); the
//           frequency is pll2's static setting.
//
// Replaces PSX_MiSTer's reconfigurable pll2 + pll_cfg in GNET_LEAN builds.
// pll2's static setting is already 53.693175 MHz (NTSC), which is also the
// ZN-2 GPU dot clock crystal (MAME zn.cpp: CXD8654Q at 53.693175 MHz). The
// runtime reconfiguration only serves PAL, fast-forward and a debug clock,
// none of which exist on G-NET. Against pll2_0002.v: the same reference
// clock (50 MHz), operation mode (direct), fractional VCO, output frequency
// (53.693175 MHz), phase and duty cycle; different pll_type ("General", not
// "Cyclone V") and pll_subtype ("General", not "Reconfigurable", so no
// reconfiguration port is built); none of pll2_0002.v's explicit counter
// settings (M, N and C counters, VCO 429.5454 MHz, fractional division,
// pll_fractional_cout 32, pll_dsm_out_sel) and none of its unused outputs 1
// to 17: Quartus chooses the counters, and the fit report's PLL summary
// shows them.

`timescale 1ns/10ps
module pll_vid_fixed
(
	input  wire refclk,
	input  wire rst,
	output wire outclk_0,
	output wire locked
);

	altera_pll #(
		.fractional_vco_multiplier("true"),
		.reference_clock_frequency("50.0 MHz"),
		.operation_mode("direct"),
		.number_of_clocks(1),
		.output_clock_frequency0("53.693175 MHz"),
		.phase_shift0("0 ps"),
		.duty_cycle0(50),
		.pll_type("General"),
		.pll_subtype("General")
	) altera_pll_i (
		.rst     (rst),
		.outclk  ({outclk_0}),
		.locked  (locked),
		.fboutclk( ),
		.fbclk   (1'b0),
		.refclk  (refclk)
	);

endmodule
